<#
.SYNOPSIS
  Regenerate Marco's OUI data: the full vendor table (oui-vendors.tsv.gz) and/or help extend the curated
  category table (oui.tsv).

.DESCRIPTION
  Marco resolves MAC vendors from TWO layered sources, both embedded in Marco.Discovery:
    * oui-vendors.tsv.gz  — the FULL registry (~40k prefixes) giving vendor NAMES. Regenerated by this script.
    * oui.tsv             — a small CURATED table adding device CATEGORY (printer/network/pc/nic/hypervisor),
                            which drives device classification. Edited by hand.

  -RefreshVendors regenerates oui-vendors.tsv.gz from the Wireshark 'manuf' registry (the IEEE oui.csv endpoint
  is frequently blocked by corporate WAFs; the Wireshark automated mirror is more reliable and current).

  -Keywords prints matching prefixes from the source so you can copy lines into the curated oui.tsv and assign
  a CATEGORY by hand.

.EXAMPLE
  pwsh build/refresh-oui.ps1 -RefreshVendors
  pwsh build/refresh-oui.ps1 -Keywords "eero","Sonos"
#>
param(
    [switch]$RefreshVendors,
    [string[]]$Keywords,
    [string]$Source = "https://www.wireshark.org/download/automated/data/manuf",
    [string]$OutGz = "$PSScriptRoot\..\Marco.Discovery\Resources\oui-vendors.tsv.gz"
)

$ErrorActionPreference = "Stop"
$tmp = Join-Path $env:TEMP "marco-manuf.dat"

if ($RefreshVendors) {
    Write-Host "Fetching $Source ..." -ForegroundColor Cyan
    Invoke-WebRequest -Uri $Source -OutFile $tmp -UseBasicParsing -TimeoutSec 120

    $seen = [System.Collections.Generic.Dictionary[string,string]]::new()
    foreach ($line in [System.IO.File]::ReadLines($tmp)) {
        if ($line.Length -eq 0 -or $line[0] -eq '#') { continue }
        $parts = $line -split "`t"
        if ($parts.Count -lt 2) { continue }
        $pfxRaw = $parts[0].Trim()
        if ($pfxRaw.Length -lt 8) { continue }
        $pfx = ($pfxRaw.Substring(0, 8) -replace '[:-]', '').ToUpper()
        if ($pfx.Length -ne 6 -or $pfx -notmatch '^[0-9A-F]{6}$') { continue }
        $vendor = if ($parts.Count -ge 3 -and $parts[2].Trim()) { $parts[2].Trim() } else { $parts[1].Trim() }
        if (-not $seen.ContainsKey($pfx)) { $seen[$pfx] = $vendor }
    }

    $sb = [System.Text.StringBuilder]::new()
    foreach ($kv in $seen.GetEnumerator()) { [void]$sb.Append($kv.Key); [void]$sb.Append("`t"); [void]$sb.Append($kv.Value); [void]$sb.Append("`n") }
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($sb.ToString())
    $fs = [System.IO.File]::Create($OutGz)
    $gz = [System.IO.Compression.GZipStream]::new($fs, [System.IO.Compression.CompressionLevel]::Optimal)
    $gz.Write($bytes, 0, $bytes.Length); $gz.Dispose(); $fs.Dispose()

    Write-Host ("Wrote {0} ({1} prefixes, {2:N0} KB)." -f $OutGz, $seen.Count, ((Get-Item $OutGz).Length/1KB)) -ForegroundColor Green
    Write-Host "Rebuild Marco.Discovery to embed the refreshed table."
}

if ($Keywords) {
    if (-not (Test-Path $tmp)) { Invoke-WebRequest -Uri $Source -OutFile $tmp -UseBasicParsing -TimeoutSec 120 }
    foreach ($kw in $Keywords) {
        Write-Host "`n== $kw ==" -ForegroundColor Yellow
        Select-String -Path $tmp -Pattern $kw -SimpleMatch | ForEach-Object { $_.Line }
    }
    Write-Host "`nFor CATEGORY, copy the prefix into Marco.Discovery/Resources/oui.tsv as PREFIX<TAB>VENDOR<TAB>Category." -ForegroundColor Green
}

if (-not $RefreshVendors -and -not $Keywords) {
    Write-Host "Nothing to do. Use -RefreshVendors to regenerate the vendor table, or -Keywords to search." -ForegroundColor Yellow
}
